    $this->assertTrue($v->passes());

    // But it's not valid if there's an unexpected key.
    $v = new Validator($trans, ['user' => ['name' => 'Duilio', 'username' => 'duilio', 'is_admin' => true]], $rules);
    $this->assertFalse($v->passes());
}

